using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var totals = CalculateTotals(invoice.Lines, account.Kind);
        var sb = new StringBuilder();
        AppendHeader(sb, invoice.Number, account);
        AppendLines(sb, invoice.Lines);
        AppendTotals(sb, totals);
        AppendPaymentTerms(sb, account.Kind);
        return sb.ToString();
    }

    private static InvoiceTotals CalculateTotals(IEnumerable<InvoiceLine> lines, AccountKind kind)
    {
        decimal net = 0m, vat = 0m;
        foreach (var line in lines)
        {
            if (line.NetAmount < 0m)
                continue;
            decimal lineVat = line.NetAmount * line.VatRate;
            net += line.NetAmount;
            vat += lineVat;
        }
        decimal discount = CalculateDiscount(net, kind);
        var gross = net + vat - discount;
        if (gross < 0m)
            gross = 0m;
        return new InvoiceTotals(net, vat, discount, gross);
    }

    private static decimal CalculateDiscount(decimal net, AccountKind kind)
    {
        if (net > 5000m) return net * 0.10m;
        if (net > 1000m && kind == AccountKind.Business) return net * 0.05m;
        return 0m;
    }

    private static void AppendHeader(StringBuilder sb, string invoiceNumber, Account account)
    {
        sb.AppendLine($"INVOICE {invoiceNumber}");
        if (account.Name.Length > 0)
            sb.AppendLine(account.Name);
        switch (account.Kind)
        {
            case AccountKind.Business:
                sb.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                sb.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                sb.AppendLine("Consumer");
                break;
        }
    }

    private static void AppendLines(StringBuilder sb, IEnumerable<InvoiceLine> lines)
    {
        foreach (var line in lines)
        {
            if (line.NetAmount < 0m)
                continue;
            decimal lineVat = line.NetAmount * line.VatRate;
            if (line.VatRate == 0m)
                sb.AppendLine($"{line.Description} {line.NetAmount} (zero-rated)");
            else if (line.VatRate >= 0.2m)
                sb.AppendLine($"{line.Description} {line.NetAmount} (std {lineVat})");
            else
                sb.AppendLine($"{line.Description} {line.NetAmount} (reduced {lineVat})");
            if (line.Description.Length > 40)
                sb.AppendLine("  (description truncated)");
        }
    }

    private static void AppendTotals(StringBuilder sb, InvoiceTotals totals)
    {
        sb.AppendLine($"NET {totals.Net} VAT {totals.Vat} DISC {totals.Discount} TOTAL {totals.Gross}");
    }

    private static void AppendPaymentTerms(StringBuilder sb, AccountKind kind)
    {
        if (kind == AccountKind.Government)
            sb.AppendLine("Remit within 30 days");
        else
            sb.AppendLine("Remit within 14 days");
    }

    private sealed record InvoiceTotals(decimal Net, decimal Vat, decimal Discount, decimal Gross);
}
